+// NewWebhookSink is the constructor for a WebhookSink.
+func NewWebhookSink(logger *zap.Logger, url string, maxBackoffDuration time.Duration, signingSecret string) *WebhookSink {
+	if maxBackoffDuration <= 0 {
+		maxBackoffDuration = time.Minute
+	}
+	return &WebhookSink{
+		logger:             logger,
+		url:                url,
+		maxBackoffDuration: maxBackoffDuration,
+		signingSecret:      []byte(signingSecret),
+		client:             &http.Client{},
+	}
+}
+
+// SendAudits POSTs the events as JSON to the configured URL. Transient
+// failures are retried with exponential backoff up to maxBackoffDuration;
+// persistent failures are logged and do not crash the service.
+func (w *WebhookSink) SendAudits(ctx context.Context, events []Event) error {
+	payload, err := json.Marshal(events)
+	if err != nil {
+		w.logger.Error("failed to marshal audit events", zap.Error(err))
+		return err
+	}
+
+	backoff := time.Second
+	for {
+		err := w.send(ctx, payload)
+		if err == nil {
+			return nil
+		}
+
+		w.logger.Error("failed to send audit events to webhook", zap.String("url", w.url), zap.Error(err))
+
+		if backoff >= w.maxBackoffDuration {
+			return err
+		}
+
+		select {
+		case <-ctx.Done():
+			return ctx.Err()
+		case <-time.After(backoff):
+		}
+
+		backoff *= 2
+		if backoff > w.maxBackoffDuration {
+			backoff = w.maxBackoffDuration
+		}
+	}
+}
+
+func (w *WebhookSink) send(ctx context.Context, payload []byte) error {
+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, w.url, bytes.NewReader(payload))
+	if err != nil {
+		return err
+	}
+
+	req.Header.Set("Content-Type", "application/json")
+	if len(w.signingSecret) > 0 {
+		mac := hmac.New(sha256.New, w.signingSecret)
+		mac.Write(payload)
+		req.Header.Set("x-flipt-webhook-signature", hex.EncodeToString(mac.Sum(nil)))
+	}
+
+	resp, err := w.client.Do(req)
+	if err != nil {
+		return err
+	}
+	defer resp.Body.Close()
+
+	if _, err := io.Copy(io.Discard, resp.Body); err != nil {
+		return err
+	}
+
